  Qmt = `[Sauvegarde automatique hors ligne]`,
  $mt = `Type d'actionneur`,
  eht = `Les actionneurs déterminent la manière dont les entrées vous répondent. S'agit-il d'un appui normal, long ou double\xA0? Sélectionnez ces actionneurs ou supprimez-les ici.`,
  tht = `Aucun\xA0: supprimer l'actionneur`,
  nht = `Si vous sélectionnez cette option, l'actionneur ainsi que toutes ses commandes seront supprimés.`,
  rht = `Appui normal`,
  iht = `Il s'agit du type d'actionneur par défaut. Quand vous appuyez sur le bouton, l'actionneur est activé jusqu'à ce que vous le relâchiez.`,
  aht = `Appui double`,
  oht = `Ce type d'actionneur nécessite un double appui bref sur l'entrée pour être activé. Si la seconde pression est maintenue, l'actionneur reste activé. Aucun autre actionneur associé au même bouton et qui peut être interrompu ne peut être activé par un double appui. L'actionneur reste en pause jusqu'à ce que l'intervalle associé au double appui soit écoulé.`,
  sht = `Appui long`,
  cht = `L'actionneur appui long s'active lorsque vous appuyez sur le bouton pendant une durée définie. Une fois cette durée écoulée, l'actionneur reste activé jusqu'à ce que vous relâchiez le bouton. Les autres actionneurs interruptibles associés au même bouton ne sont pas activés tant que l'appui long est maintenu.`,
  lht = `Début d'appui`,
  uht = `Ce type d'actionneur s'active quand on appuie sur le bouton. Il se désactive immédiatement, même si le bouton est maintenu. Combinez-le avec l'actionneur appui relâché pour convertir une bascule en maintien, par exemple pour une commande «\xA0Bascule de la position accroupie\xA0».`,
  dht = `Appui relâché`,
  fht = `L'actionneur appui relâché s'active puis se désactive lorsque le bouton est relâché.`,
  pht = `Appui léger`,
  mht = `L'actionneur appui léger s'active lors d'un appui partiel sur le bouton ou la gâchette.`,
  hht = `Analogique`,
  ght = `L'actionneur analogique génère une entrée en sortie analogique.`,
  _ht = `Combinaison de boutons`,
  vht = `L'actionneur de combinaison de boutons s'active quand vous appuyez en même temps sur le bouton associé à l'actionneur et la combinaison de boutons.`,
  yht = `Commande`,
  bht = `Vous pouvez assigner une ou plusieurs commandes à cet actionneur.`,
  xht = `Activer le stick analogique ou le pavé tactile`,
  Sht = `Les contrôleurs virtuels peuvent émuler un stick ou un pavé tactile virtuel lorsque vous appuyez sur un bouton. Cette option est pratique pour les mitrailleuses, car le doigt qui appuie sur la gâchette peut aussi servir à viser.`,
  Cht = `Aucun stick analogique ou pavé tactile`,
  wht = `Cet actionneur se comporte normalement et n'active pas de stick analogique ou de pavés tactiles virtuels.`,
  Tht = `Activer le stick analogique gauche`,
  Eht = `Tant que ces boutons sont maintenus, le même doigt contrôle également le stick analogique virtuel gauche.`,
  Dht = `Activer le stick analogique droit`,
  Oht = `Tant que ces boutons sont maintenus, le même doigt contrôle également le stick analogique virtuel droit.`,
  kht = `Activer le pavé tactile central`,
  Aht = `Tant que ces boutons sont maintenus, le même doigt contrôle également le pavé tactile virtuel central.`,
  jht = `Activer le pavé tactile gauche`,
  Mht = `Tant que ces boutons sont maintenus, le même doigt contrôle également le pavé tactile virtuel gauche.`,
  Nht = `Activer le pavé tactile droit`,
  Pht = `Tant que ces boutons sont maintenus, le même doigt contrôle également le pavé tactile virtuel droit.`,
  Fht = `Actionneur actif`,
  Iht = `Avec ce réglage, l'actionneur reste actif après que vous avez relâché l'entrée associée, jusqu'à ce que vous appuyiez à nouveau dessus.`,
  Lht = `Actionneur actif\xA0: oui`,
  Rht = `L'actionneur reste actif après que vous avez relâché l'entrée associée, jusqu'à ce que vous appuyiez à nouveau dessus.`,
  zht = `Actionneur actif\xA0: non`,
  Bht = `L'actionneur se comporte comme un bouton traditionnel et reste actif jusqu'à ce que vous le relâchiez.`,
  Vht = `Inversion de l'entrée`,
  Hht = `Inversion de l'entrée\xA0: le relâchement du bouton activera la commande tandis que le fait d'appuyer dessus désactivera la commande.`,
  Uht = `Interruptible`,
  Wht = `Les actionneurs interruptibles peuvent être mis en pause ou arrêtés par les autres actionneurs. Par exemple, un actionneur appui long peut interrompre un actionneur appui normal afin que ce dernier ne soit activé que si l'actionneur appui long ne l'est pas. Si l'actionneur n'est pas interruptible, son comportement n'est pas affecté par les autres actionneurs.`,
  Ght = `Interruptible\xA0: oui`,
  Kht = `Cet actionneur est mis en pause ou s'arrête quand d'autres actionneurs entrent en jeu. Son activation ne peut avoir lieu qu'une fois les conditions d'autres actionneurs, tels que double appui ou appui long, remplies. Si les autres actionneurs se déclenchent, cet actionneur n'est pas activé.`,
  qht = `Interruptible\xA0: non`,
  Jht = `Cet actionneur ignore les autres actionneurs et s'active ou se désactive comme s'il n'y avait que lui.`,
  Yht = `Début du délai de déclenchement`,
  Xht = `Lorsque vous appuyez sur ce bouton, l'actionneur respecte ce délai avant de se déclencher, ce qui décale également la durée de l'appui sur le bouton. Par exemple, si la fin du délai n'est pas définie, la durée de l'appui sur le bouton n'est pas écourtée, mais décalée.`,
  Zht = `Fin du délai de déclenchement`,
  Qht = `Une fois le bouton relâché, l'actionneur attend que ce délai se soit écoulé avant de se désactiver. Le temps d'activation du bouton est donc plus long que le temps d'appui.`,
  $ht = `Intensité du retour haptique`,
